import type { ParseResult } from "./types.ts";

const GENERATED_HEADER =
  "// Generated by `pnpm parse`. It is the parser's output, not a hand-written file.";

/**
 * The result as a typed data file: a `.ts` module whose literal is checked
 * against the contract by the compiler, so a shape that drifts stops the build
 * rather than surfacing three screens later.
 */
export function toTypedModule(result: ParseResult, typesImportPath: string): string {
  return [
    GENERATED_HEADER,
    `import type { ParseResult } from ${JSON.stringify(typesImportPath)};`,
    "",
    `export const parsed: ParseResult = ${JSON.stringify(result, null, 2)};`,
    "",
  ].join("\n");
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function hasNumbers(value: Record<string, unknown>, keys: readonly string[]): boolean {
  return keys.every((key) => typeof value[key] === "number");
}

/**
 * Checks the shape a reader relies on: the summary fields and the arrays. It
 * does not re-check every element — the contract itself is the guarantee, and
 * this is here so a wrong or hand-edited file fails loudly instead of printing
 * nonsense.
 */
export function isParseResult(value: unknown): value is ParseResult {
  if (!isRecord(value)) return false;
  if (!isRecord(value.repository) || !isRecord(value.stats)) return false;
  if (!isRecord(value.coverage)) return false;
  if (typeof value.repository.name !== "string") return false;
  if (typeof value.repository.root !== "string") return false;
  if (typeof value.repository.framework !== "string") return false;

  return [
    "stats",
    "coverage",
    "files",
    "edges",
    "imports",
    "skippedFiles",
    "skippedDirectories",
    "entryPoints",
  ].every((key) => {
    if (key === "stats") {
      return hasNumbers(value.stats as Record<string, unknown>, [
        "filesFound",
        "filesParsed",
        "filesSkipped",
        "folders",
        "modules",
        "importsSeen",
        "edges",
      ]);
    }
    if (key === "coverage") {
      return hasNumbers(value.coverage as Record<string, unknown>, [
        "seen",
        "resolved",
        "external",
        "excluded",
        "unresolved",
      ]);
    }
    return Array.isArray(value[key]);
  });
}

/** The result out of an imported data module, or an error naming what was wrong. */
export function readParseResultModule(module: unknown, label: string): ParseResult {
  if (!isRecord(module) || !("parsed" in module)) {
    throw new Error(`${label} does not export "parsed"`);
  }
  const parsed = module.parsed;
  if (!isParseResult(parsed)) {
    throw new Error(`${label} does not hold a parse result`);
  }
  return parsed;
}
